#!/usr/bin/env python3
"""Bring the week READMEs up to date with the latest plan.

Run it after unzipping an update pack:   python scripts/upgrade_plan.py

What it does, for every week:
  - rewrites task lines whose text changed (new timings, new capstone tasks)
  - appends tasks that are new (crypto, AI, explainer, apps and capstone threads)
  - updates the week title, goal and "Ship" lines
What it never does:
  - untick anything: a task you ticked stays ticked, even if its text changes
  - touch your notes below the "---" line (What I built, Time spent, ...)
Task numbers stay the same, so the tracker ids (x1t5, ...) still match.
Running it twice does nothing the second time.
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FOLDER_RE = re.compile(r"^week(\d+)(?:-(\d+))?-")
BOX_RE = re.compile(r"^\s*[-*] \[( |x|X)\] (.*)$", re.M)
WEEK_HEAD_RE = re.compile(r"^## Week (\d+):.*$", re.M)
PLAN = json.loads(r'''{"1":{"title":"The mental model, keys and signatures","goal":"Understand why hash-linking plus proof-of-work makes history expensive to rewrite, then add real ownership with ECDSA signatures and Merkle roots.","deliver":"pow_demo.py and Project 0 (toy_chain.py with a tamper test)","tasks":[{"head":"Learn (30 min): Watch 3Blue1Brown's bitcoin video end to end","links":"[But how does bitcoin actually work?](https://www.youtube.com/watch?v=bBC-nXj3Ng4)"},{"head":"Learn (45 min): Click through all five pages of the blockchain demo: hash, block, blockchain, distributed, tokens","links":"[andersbrownworth.com/blockchain](https://andersbrownworth.com/blockchain/)"},{"head":"Learn (45 min): Read the Bitcoin whitepaper, sections 1–6. Don't worry about the math yet","links":"[bitcoin.pdf](https://bitcoin.org/bitcoin.pdf)"},{"head":"Build (30 min): Create the blockchain-learning repo with a README and a /week01 folder","links":""},{"head":"Build (90 min): Using Python's hashlib, find a nonce that gives 4 leading hex zeros, then time 5 and 6 zeros","links":"[hashlib docs](https://docs.python.org/3/library/hashlib.html)"},{"head":"Write (30 min): Log: explain in five sentences why editing one block invalidates every block after it","links":""},{"head":"Learn (45 min): Read Cloudflare's primer on elliptic-curve cryptography","links":"[A (relatively easy to understand) primer on ECC](https://blog.cloudflare.com/a-relatively-easy-to-understand-primer-on-elliptic-curve-cryptography/)"},{"head":"Learn (45 min): Princeton textbook, chapter 1: hash pointers, Merkle trees, digital signatures","links":"[Princeton book PDF](https://d28rh4a8wq0iu5.cloudfront.net/bitcointech/readings/princeton_bitcoin_book.pdf)"},{"head":"Build (150 min): Build Project 0: Block class, SHA-256 linking, adjustable-difficulty PoW, transactions signed with the ecdsa library (SECP256k1), a Merkle root per block, and validate_chain()","links":"[python-ecdsa](https://pypi.org/project/ecdsa/)"},{"head":"Build (30 min): Tamper test: change one transaction in block 2 and confirm validation fails at the right block","links":""},{"head":"Write (15 min): Log: what a signature proves, and what it does not","links":""},{"head":"Crypto (30 min): The three security properties of hash functions (preimage, second-preimage and collision resistance), and which one proof-of-work relies on","links":"[A Graduate Course in Applied Cryptography (Boneh & Shoup, free)](https://toc.cryptobook.us/) · [Cryptography I (Dan Boneh, Coursera)](https://www.coursera.org/learn/crypto)"},{"head":"AI (15 min): Ask an LLM to explain proof-of-work, then use the whitepaper to find one thing it got wrong or oversimplified. Note it in your log","links":""}]},"2":{"title":"Bitcoin: UTXOs, raw transactions and mining","goal":"Run your own node, see that Bitcoin has no balances, and build and decode a transaction by hand.","deliver":"A regtest node, a UTXO version of your toy chain, and raw_tx.py with a decoded transaction","tasks":[{"head":"Learn (60 min): Mastering Bitcoin: the 'Introduction' and 'How Bitcoin Works' chapters","links":"[bitcoinbook on GitHub](https://github.com/bitcoinbook/bitcoinbook)"},{"head":"Learn (45 min): learnmeabitcoin: the transaction and UTXO pages","links":"[learnmeabitcoin technical](https://learnmeabitcoin.com/technical/)"},{"head":"Build (60 min): Install Bitcoin Core, start it with -regtest, mine 101 blocks, send coins to a second address with bitcoin-cli","links":"[Bitcoin Core download](https://bitcoincore.org/en/download/) · [Bitcoin developer examples (regtest)](https://developer.bitcoin.org/examples/testing.html)"},{"head":"Build (60 min): Change your toy chain to UTXOs: inputs reference earlier outputs, and double spends are rejected","links":""},{"head":"Learn (45 min): Mastering Bitcoin: the 'Keys and Addresses' and 'Transactions' chapters","links":"[bitcoinbook on GitHub](https://github.com/bitcoinbook/bitcoinbook)"},{"head":"Learn (30 min): learnmeabitcoin: Script, P2PKH and P2WPKH","links":"[learnmeabitcoin technical](https://learnmeabitcoin.com/technical/)"},{"head":"Build (105 min): With python-bitcoinlib, build, sign and broadcast a raw transaction on regtest, then run decoderawtransaction on it","links":"[python-bitcoinlib](https://github.com/petertodd/python-bitcoinlib)"},{"head":"Learn (45 min): Mastering Bitcoin: the mining and consensus chapter","links":"[bitcoinbook on GitHub](https://github.com/bitcoinbook/bitcoinbook)"},{"head":"Learn (30 min): Re-read the whitepaper, sections 7–11, including the attacker probability calculation","links":"[bitcoin.pdf](https://bitcoin.org/bitcoin.pdf)"},{"head":"Write (15 min): Log: what the locking and unlocking scripts did in your transaction, and why a 51% attacker still can't steal coins","links":""},{"head":"Crypto (30 min): Schnorr signatures and Taproot. Why Bitcoin added them alongside ECDSA (linearity, key aggregation)","links":"[BIP-340: Schnorr signatures](https://github.com/bitcoin/bips/blob/master/bip-0340.mediawiki) · [learnmeabitcoin: technical guide](https://learnmeabitcoin.com/technical/)"},{"head":"Explain (45 min): Explainer #1: write \"I built a blockchain from scratch\" in blog/ (600–900 words, weeks 1–2). Optional: record a 5-minute video teaching it and link it in the post","links":""},{"head":"Apps (30 min): Cryptocurrencies as money: Bitcoin's fixed supply and halvings, why stablecoins exist, and what a CBDC is. Look up the eNaira and one other CBDC on the tracker and note why adoption differed","links":"[ethereum.org: stablecoins](https://ethereum.org/en/stablecoins/) · [Atlantic Council CBDC tracker](https://www.atlanticcouncil.org/cbdctracker/)"}]},"3":{"title":"Consensus, attacks and proof-of-stake","goal":"Learn the problem blockchains solve, then watch forks, partitions and reorgs happen in your own network simulation.","deliver":"Project 2: a multi-node simulation with gossip, fork resolution, a partition that heals, and stake-weighted proposers","tasks":[{"head":"Learn (75 min): Roughgarden: Lecture 1 (overview, state machine replication, consistency and liveness)","links":"[Foundations of Blockchains playlist](https://www.youtube.com/playlist?list=PLEGCF-WLh2RLOHv_xUGLqRts_9JxrckiA)"},{"head":"Learn (30 min): Decentralized Thoughts on Nakamoto consensus","links":"[Nakamoto's longest-chain-wins protocol](https://decentralizedthoughts.github.io/2021-10-15-Nakamoto-Consensus/)"},{"head":"Learn (45 min): Lamport, Shostak and Pease: The Byzantine Generals Problem, sections 1–3","links":"[byz.pdf](https://lamport.azurewebsites.net/pubs/byz.pdf)"},{"head":"Build (95 min): Build a simulation of 4 nodes that mine and gossip blocks with random network delays and resolve forks by the longest chain","links":""},{"head":"Write (30 min): Log: how often did forks happen, and how did delay change that?","links":""},{"head":"Learn (60 min): Roughgarden: the lectures on selfish mining and proof-of-stake sybil resistance","links":"[Foundations of Blockchains playlist](https://www.youtube.com/playlist?list=PLEGCF-WLh2RLOHv_xUGLqRts_9JxrckiA)"},{"head":"Learn (45 min): ethereum.org: proof-of-stake and Gasper","links":"[Proof-of-stake](https://ethereum.org/en/developers/docs/consensus-mechanisms/pos/) · [Gasper](https://ethereum.org/en/developers/docs/consensus-mechanisms/pos/gasper/)"},{"head":"Learn (30 min): Skim Eyal and Sirer, Majority is not Enough (selfish mining)","links":"[Selfish mining paper](https://www.cs.cornell.edu/~ie53/publications/btcProcFC.pdf)"},{"head":"Build (110 min): Split your network into two halves for 20 blocks, heal it, and log the reorg. Then add stake-weighted proposer selection","links":""},{"head":"Write (30 min): Log: a table comparing PoW and PoS on security, finality, energy and who can participate","links":""},{"head":"Crypto (30 min): BLS signature aggregation and VRFs. How proof-of-stake compresses thousands of validator votes and picks proposers fairly","links":"[ethereum.org: proof-of-stake keys (BLS)](https://ethereum.org/en/developers/docs/consensus-mechanisms/pos/keys/) · [A Graduate Course in Applied Cryptography (Boneh & Shoup, free)](https://toc.cryptobook.us/)"},{"head":"Apps (20 min): How cryptocurrencies change their rules: read about Bitcoin's block-size dispute and Ethereum's DAO fork. Who decided, and what happened to people who disagreed?","links":"[ethereum.org: history of Ethereum](https://ethereum.org/en/history/)"}]},"4":{"title":"The Ethereum model and Solidity fluency","goal":"Understand accounts, gas and the EVM, deploy your first contract to Sepolia, and get comfortable writing Solidity.","deliver":"SimpleStorage on Sepolia and five small contracts in /week04","tasks":[{"head":"Learn (45 min): Read the Ethereum whitepaper","links":"[ethereum.org/whitepaper](https://ethereum.org/en/whitepaper/)"},{"head":"Learn (60 min): ethereum.org docs: accounts, transactions, gas and fees, the EVM","links":"[Ethereum developer docs](https://ethereum.org/en/developers/docs/)"},{"head":"Build (90 min): Cyfrin Updraft: Blockchain Basics, then the first Remix lessons of Solidity Smart Contract Development","links":"[Blockchain Basics](https://updraft.cyfrin.io/courses/blockchain-basics) · [Updraft course list](https://updraft.cyfrin.io/courses) · [Remix IDE](https://remix.ethereum.org/)"},{"head":"Build (30 min): Set up a wallet in a separate browser profile, get Sepolia ETH from a faucet, deploy SimpleStorage","links":"[Google Cloud Sepolia faucet](https://cloud.google.com/application/web3/faucet/ethereum/sepolia)"},{"head":"Write (30 min): Log: the difference between a Bitcoin UTXO and an Ethereum account","links":""},{"head":"Learn (75 min): Work through the first ~25 Solidity by Example pages, running each in Remix","links":"[solidity-by-example.org](https://solidity-by-example.org/)"},{"head":"Learn (70 min): Updraft: continue the Solidity course (the FundMe section)","links":"[Updraft courses](https://updraft.cyfrin.io/courses)"},{"head":"Build (75 min): Write 5 small contracts without looking: a counter, a whitelist, a vault, a voting contract, a timelock","links":""},{"head":"Write (30 min): Log: what surprised you about gas costs","links":""},{"head":"Crypto (20 min): Keccak-256 vs. SHA-3, and how an Ethereum address is derived from a public key. Derive one yourself in Python","links":"[ethereum.org: accounts](https://ethereum.org/en/developers/docs/accounts/)"},{"head":"Explain (45 min): Explainer #2: write \"How strangers agree: consensus in plain words\" in blog/ (600–900 words, weeks 3–4). Optional: record a 5-minute video teaching it and link it in the post","links":""},{"head":"Apps (30 min): Exchanges and wallets: custodial vs. self-custody, centralised exchanges vs. DEXs, and what the FTX collapse showed about 'not your keys, not your coins'","links":"[ethereum.org: wallets](https://ethereum.org/en/wallets/) · [ethereum.org: DeFi](https://ethereum.org/en/defi/)"}]},"5":{"title":"Foundry and your ERC-20","goal":"Move to a real toolchain, write a token from the spec, fuzz it, deploy it and verify it.","deliver":"Project 3a: an ERC-20 with unit and fuzz tests, verified on Sepolia Etherscan","tasks":[{"head":"Learn (45 min): Foundry: getting started, then forge test basics. Install the pinned version the repo uses: foundryup --install v1.5.1 (see toolchain.env)","links":"[Foundry getting started](https://www.getfoundry.sh/introduction/getting-started)"},{"head":"Learn (60 min): Updraft Foundry Fundamentals: the first section","links":"[Foundry Fundamentals](https://updraft.cyfrin.io/courses/foundry)"},{"head":"Build (120 min): Write an ERC-20 by reading the spec only. Test transfer, approve, transferFrom and the failure cases","links":"[EIP-20](https://eips.ethereum.org/EIPS/eip-20)"},{"head":"Write (30 min): Log: what the allowance pattern protects, and its known approval race","links":""},{"head":"Learn (20 min): Compare your token with OpenZeppelin's ERC20 source","links":"[OpenZeppelin Contracts](https://docs.openzeppelin.com/contracts/) · [OpenZeppelin Wizard](https://wizard.openzeppelin.com/)"},{"head":"Learn (20 min): Foundry docs: fuzz testing and forge scripts","links":"[Foundry guides](https://www.getfoundry.sh/guides)"},{"head":"Build (150 min): Add fuzz tests, deploy with forge script to Sepolia, verify the contract on Etherscan","links":"[Sepolia Etherscan](https://sepolia.etherscan.io/)"},{"head":"Learn (15 min): Updraft Foundry Fundamentals: continue","links":"[Foundry Fundamentals](https://updraft.cyfrin.io/courses/foundry)"},{"head":"Write (30 min): Log: one bug the fuzzer found, or why it found none","links":""},{"head":"AI (30 min): Have an LLM write fuzz tests for your ERC-20, then check which ones actually test something. Keep the good ones and note the useless ones in your log","links":""},{"head":"Capstone (30 min): Capstone C: turn your ERC-20 into TestUSD, the stablecoin for the payment rail. Use 6 decimals, add a capped faucet mint for testers, write tests, and keep it in trust-stack/ (the shared capstone project)","links":""},{"head":"Capstone (20 min): Demo stage 1: add forge-std as a submodule (see trust-stack/README.md), write script/demo/01_TestUSD.s.sol from the template in script/demo/README.md, run make demo, push, and check the Trust stack run on GitHub shows stage 01 passed","links":"[Foundry: scripting](https://www.getfoundry.sh/guides)"},{"head":"Capstone (15 min): Testing setup: run python scripts/set_github_user.py <your-username>, open TESTING.md, and start the rules-to-tests table with TestUSD's tests. Check coverage and Slither pass in CI","links":"[Slither](https://github.com/crytic/slither)"},{"head":"Capstone (15 min): Docker check (optional, see DOCKER.md): install Docker Desktop, then from trust-stack/ run make docker-test and make docker-demo. They should match your normal run, and the docker job in the Trust stack run on GitHub should be green","links":"[Docker: get started](https://docs.docker.com/get-started/get-docker/)"}]},"6":{"title":"Escrow and an on-chain NFT","goal":"Write your first contract that holds value, then an NFT whose image lives entirely on-chain. End with frontend prep for next week.","deliver":"Project 3b (Escrow.sol) and Project 3c (on-chain SVG NFT)","tasks":[{"head":"Learn (20 min): Solidity docs: Security Considerations (read before writing code that holds money)","links":"[Security considerations](https://docs.soliditylang.org/en/latest/security-considerations.html)"},{"head":"Learn (20 min): Solidity by Example: Sending Ether, Payable, and the Re-entrancy hack","links":"[solidity-by-example.org](https://solidity-by-example.org/)"},{"head":"Build (135 min): Build Escrow: deposit, release by buyer or arbiter, refund after a deadline, dispute. Emit events, use checks-effects-interactions","links":""},{"head":"Write (30 min): Log: every state the escrow can be in, as a small state diagram","links":""},{"head":"Learn (20 min): Read EIP-721","links":"[EIP-721](https://eips.ethereum.org/EIPS/eip-721)"},{"head":"Learn (15 min): OpenZeppelin ERC-721 docs and the Wizard","links":"[OpenZeppelin Contracts](https://docs.openzeppelin.com/contracts/) · [Wizard](https://wizard.openzeppelin.com/)"},{"head":"Build (80 min): Build an NFT whose tokenURI returns base64 JSON with an SVG generated in Solidity","links":""},{"head":"Write (20 min): Log: what an NFT actually owns, and what lives off-chain in most NFTs","links":""},{"head":"Learn (20 min): viem: getting started, reading and writing contracts","links":"[viem.sh](https://viem.sh/)"},{"head":"Learn (10 min): Scaffold-ETH 2 docs: hooks and deploying","links":"[docs.scaffoldeth.io](https://docs.scaffoldeth.io/) · [wagmi](https://wagmi.sh/)"},{"head":"Crypto (30 min): EIP-712 typed-data signatures and replay protection. Sign an escrow release off-chain and verify it in Solidity","links":"[EIP-712](https://eips.ethereum.org/EIPS/eip-712) · [OpenZeppelin EIP712 utilities](https://docs.openzeppelin.com/contracts/5.x/api/utils#EIP712)"},{"head":"Explain (45 min): Explainer #3: write \"Replacing a middleman with an escrow contract, and what it can't replace\" in blog/ (600–900 words, weeks 5–6). Optional: record a 5-minute video teaching it and link it in the post","links":""},{"head":"Apps (30 min): Marketplaces: how on-chain marketplaces work (listings, signed orders, escrow, royalties, disputes). Skim the Seaport contracts and sketch how your escrow and NFT could become a small marketplace","links":"[Seaport (OpenSea's marketplace protocol)](https://github.com/ProjectOpenSea/seaport)"},{"head":"Write (15 min): Write trust-stack/README.md: the four parts (A provenance, B marketplace, C payment rail, D credentials) in your own words, how they connect, and what 'working and tested' means for each","links":""},{"head":"Capstone (30 min): Capstone B: copy your escrow into trust-stack/ as Marketplace.sol. list(batchId, price) is allowed only for sellers with a valid credential (check the mock for now), buyers pay in TestUSD into escrow, and completed trades count as reputation. Test it against the mocks","links":""},{"head":"Capstone (30 min): Integration design: write trust-stack/INTERFACES.md and the Solidity interfaces the parts talk through (ICredentialRegistry.isValid(account, role), IProvenance.batchStatus(batchId), IMarketplace.list(batchId, price)), plus mock versions of D and A so the marketplace can be tested against them now","links":""},{"head":"Capstone (15 min): Traceability design: in trust-stack/POLICY.md, define a batch's journey (harvested → packed → shipped → received), which role may sign each step (farmer, cooperative, transporter, inspector, buyer), and one product policy, e.g. tomatoes: 2–8 °C, at most 48 h in transit, inspection required","links":""},{"head":"Capstone (20 min): Rules to tests: for every rule in your POLICY.md, add a row to TESTING.md with a named test (e.g. test_RevertWhen_TransporterSignsInspection) and write the empty test so CI shows what's still missing","links":""},{"head":"Capstone (15 min): Demo stages 2–3 with the mocks: issue roles and list batch 1, so make demo now runs stages 01–03","links":""}]},"7":{"title":"A dApp frontend, then start breaking contracts","goal":"Ship a usable escrow frontend, then learn the common vulnerability classes by exploiting them.","deliver":"Project 3d (escrow dApp with a 2-minute demo) and Ethernaut levels 0–5","tasks":[{"head":"Build (150 min): Build the frontend: connect wallet, create an escrow, release or refund, and list events","links":""},{"head":"Write (30 min): Record a 2-minute demo and write the log","links":""},{"head":"Learn (45 min): Updraft Smart Contract Security: the introduction section","links":"[Smart Contract Security](https://updraft.cyfrin.io/courses/security)"},{"head":"Learn (20 min): Read two rekt.news post-mortems: one re-entrancy, one oracle manipulation","links":"[rekt.news](https://rekt.news/)"},{"head":"Build (105 min): Ethernaut levels 0–5","links":"[ethernaut.openzeppelin.com](https://ethernaut.openzeppelin.com/)"},{"head":"Write (30 min): Log: for each level, the bug in one line","links":""},{"head":"Build (60 min): Install Slither and run it on your ERC-20, Escrow and NFT","links":"[Slither](https://github.com/crytic/slither)"},{"head":"Learn (30 min): Foundry docs: invariant testing","links":"[Foundry guides](https://www.getfoundry.sh/guides)"},{"head":"AI (30 min): Give an LLM one vulnerable Ethernaut contract without the hint. Compare its answer with what you found yourself","links":"[Ethernaut](https://ethernaut.openzeppelin.com/)"},{"head":"Capstone (30 min): Capstone B: point your escrow frontend at Marketplace.sol so you can list, buy and release from the browser","links":""},{"head":"Capstone (30 min): Integration test v1 (test/Integration.t.sol): mock credential → list → pay in TestUSD → release, passing in CI alongside the demo","links":""},{"head":"Capstone (20 min): Demo stage 4 (payment into escrow). Then open your repo in GitHub Codespaces from the README badge and run make demo there, to confirm a stranger can run it with no setup","links":""},{"head":"Capstone (20 min): Invariant tests: escrow always holds what it owes, and TestUSD's total supply equals the sum of balances (invariant_EscrowSolvent, invariant_SupplyEqualsBalances)","links":"[Foundry guides (invariant testing)](https://www.getfoundry.sh/guides)"}]},"8":{"title":"Deeper exploits and your own audit","goal":"Solve harder levels, then treat your earlier contracts as someone else's and write a real findings report.","deliver":"Project 4: AUDIT.md with severity-ranked findings, invariant tests and fixes","tasks":[{"head":"Build (135 min): Ethernaut: Re-entrancy, Elevator, Privacy and one more level of your choice","links":"[Ethernaut](https://ethernaut.openzeppelin.com/)"},{"head":"Learn (45 min): ConsenSys best practices: the attacks section","links":"[Smart contract best practices](https://consensys.github.io/smart-contract-best-practices/)"},{"head":"Write (30 min): Log: which Slither findings were real and which were noise","links":""},{"head":"Build (60 min): Damn Vulnerable DeFi: challenge 1 (Unstoppable)","links":"[damnvulnerabledefi.xyz](https://www.damnvulnerabledefi.xyz/)"},{"head":"Build (165 min): Audit your Escrow, ERC-20 and NFT: write each finding (severity, description, fix), add invariant tests, and fix the code","links":""},{"head":"Write (30 min): Log: the one mistake you'll never make again","links":""},{"head":"Learn (15 min): Read one more rekt.news post-mortem and match it to a bug class you now know","links":"[rekt.news](https://rekt.news/)"},{"head":"AI (30 min): AI-assisted audit: run an LLM over your escrow and compare its findings with Slither's and your own. Count true and false positives in AUDIT.md","links":""},{"head":"Explain (45 min): Explainer #4: write \"What I learned auditing my own smart contracts\" in blog/ (600–900 words, weeks 7–8). Optional: record a 5-minute video teaching it and link it in the post","links":""},{"head":"Capstone (15 min): Add the integration to your audit: what breaks if a mock is swapped for a malicious contract, or a batch id is reused? Note findings in AUDIT.md","links":""},{"head":"Capstone (30 min): Attack tests in test/Attacks.t.sol: replayed signature, reused batch id, re-entrancy on release, a stranger releasing escrow. Each must fail the way TESTING.md says","links":""}]},"9":{"title":"AMMs, oracles, rollups","goal":"Build x·y=k, see why a spot price is a dangerous oracle, compare rollups by their real risks, and decide exactly what your capstone puts on-chain.","deliver":"Project 5 (AMM with a fuzz test), the 'do you need a blockchain?' memo, and SPEC.md for the capstone","tasks":[{"head":"Learn (30 min): Finematics: the AMM and Uniswap explainers","links":"[Finematics channel](https://www.youtube.com/@Finematics)"},{"head":"Learn (30 min): Uniswap v2 whitepaper, sections 1–3","links":"[Uniswap v2 whitepaper](https://uniswap.org/whitepaper.pdf)"},{"head":"Build (75 min): Build an AMM with addLiquidity, removeLiquidity and swap with a 0.3% fee. Fuzz-test that k never decreases","links":""},{"head":"Learn (60 min): DeFi MOOC lecture: Oracles (Ari Juels)","links":"[Oracles lecture](https://www.youtube.com/watch?v=vFcW18ZpPZ4)"},{"head":"Learn (30 min): Chainlink: Data Feeds overview","links":"[docs.chain.link](https://docs.chain.link/)"},{"head":"Learn (30 min): Vitalik Buterin: An incomplete guide to rollups","links":"[vitalik.eth.limo](https://vitalik.eth.limo/general/2021/01/05/rollup.html)"},{"head":"Learn (30 min): L2BEAT: read the FAQ, then compare two rollups on its risk dashboard","links":"[L2BEAT](https://l2beat.com/) · [L2BEAT FAQ](https://l2beat.com/faq)"},{"head":"Write (60 min): Write a 'do you need a blockchain?' memo for remittances, land registry and cold-chain provenance","links":""},{"head":"Write (90 min): Capstone SPEC.md for the whole trust stack: actors, trust assumptions, what is on-chain vs. off-chain for each part, the threat model, and the end-to-end test you'll write in week 11","links":""},{"head":"Write (30 min): Log: slippage on a small pool vs. a large one, with numbers from your tests","links":""},{"head":"Crypto (30 min): Commitments and Merkle proofs. Write a Merkle proof verifier in Solidity and test it (you'll reuse it in the capstone)","links":"[OpenZeppelin MerkleProof](https://docs.openzeppelin.com/contracts/5.x/api/utils#MerkleProof)"},{"head":"Apps (30 min): Payments and remittances in Africa: compare the cost of sending $200 to Nigeria or Rwanda by bank, mobile money and a stablecoin. Add the numbers to your 'do you need a blockchain?' memo","links":"[World Bank: Remittance Prices Worldwide](https://remittanceprices.worldbank.org/)"},{"head":"Capstone (60 min): Capstone D: CredentialRegistry.sol with roles (farmer, cooperative, transporter, inspector, buyer). An issuer signs EIP-712 credentials, each cohort is Merkle-rooted on-chain, and isValid(account, role) replaces the mock in the integration test","links":"[EIP-712](https://eips.ethereum.org/EIPS/eip-712)"},{"head":"Capstone (15 min): Credential tests: a revoked credential can't sign or list (test_RevertWhen_RevokedCredential). Switch demo stage 2 from the mock to the real registry","links":""}]},"10":{"title":"Capstone I: the device signs, the contract verifies","goal":"Make an ESP32 hold its own key and sign batched readings, and write the contract that accepts only signatures from registered devices.","deliver":"ESP32 firmware that signs Merkle roots of readings, and a tested SensorRegistry contract","tasks":[{"head":"Learn (15 min): Browse the Trezor firmware repo: the crypto folder and the security docs","links":"[trezor-firmware](https://github.com/trezor/trezor-firmware)"},{"head":"Learn (15 min): SGX.Fail: skim the list of TEE attacks","links":"[sgx.fail](https://sgx.fail/)"},{"head":"Learn (15 min): OpenZeppelin ECDSA and MessageHashUtils docs","links":"[OZ ECDSA](https://docs.openzeppelin.com/contracts/5.x/api/utils#ECDSA)"},{"head":"Learn (15 min): Study how OpenTimestamps anchors many hashes with one transaction","links":"[opentimestamps.org](https://opentimestamps.org/)"},{"head":"Build (150 min): Capstone A: on an ESP32, generate a key with micro-ecc or trezor-crypto, hash a sensor reading with keccak256, and print r, s, v and the address. If the board fights you, start with a Python device simulator and swap the board in later","links":"[micro-ecc](https://github.com/kmackay/micro-ecc) · [ESP-IDF](https://docs.espressif.com/projects/esp-idf/en/latest/esp32/)"},{"head":"Build (90 min): Batch readings on the device or a gateway: build a Merkle tree and sign the root instead of each reading","links":"[OZ MerkleProof](https://docs.openzeppelin.com/contracts/5.x/api/utils#MerkleProof)"},{"head":"Build (165 min): Capstone A: ProvenanceAnchor.sol as a trace registry. createBatch(product, policyId); recordEvent(batchId, stage, dataRoot) only by an actor with the right role credential and in the right order; accept sensor Merkle roots only from registered devices (ecrecover). Test with vm.sign, then with a real ESP32 signature","links":""},{"head":"Write (30 min): Log: what this proves (the device signed it) and what it doesn't (the reading is true)","links":""},{"head":"Explain (45 min): Explainer #5: write \"Teaching a sensor to sign its own data\" in blog/ (600–900 words, weeks 9–10). Optional: record a 5-minute video teaching it and link it in the post","links":""},{"head":"Capstone (30 min): Replace the provenance mock in the integration test: create a batch, record its events and a signed sensor root, list it, pay, release. Update demo.sh","links":""},{"head":"Capstone (30 min): Firmware checks: run make vectors, make your ESP32 reproduce test_vectors.json byte for byte, and add firmware/tools/Vectors.t.sol.example to test/ so CI proves tampered and unregistered readings are rejected. Demo stage 5 uses sample_readings.json, so it runs without hardware","links":""}]},"11":{"title":"Capstone II: connect all four parts and ship","goal":"Deploy the whole trust stack to an L2 testnet, prove it works end to end with one test, and publish it.","deliver":"All four parts on an L2 testnet, one end-to-end test passing, and a README with an architecture diagram, demo video and post","tasks":[{"head":"Build (90 min): Deploy all four parts to an L2 testnet such as Base Sepolia: TestUSD, Marketplace, CredentialRegistry and ProvenanceAnchor. Verify each contract on the explorer","links":"[Base docs (Base Sepolia testnet)](https://docs.base.org/)"},{"head":"Build (150 min): End-to-end flow in the integration test and demo.sh: a credentialed farmer creates a batch, a transporter records pickup and delivery with the ESP32's signed readings, the batch is checked against its policy, and the buyer's TestUSD in escrow is released only if the batch is compliant; otherwise the buyer is refunded","links":""},{"head":"Build (15 min): Capstone C demo: a script that sends a TestUSD payment with a receipt event and prints its cost and time next to the bank and mobile-money figures from week 9","links":""},{"head":"Build (45 min): Security pass on all four contracts: Slither, your Project 4 checklist, and invariant tests","links":"[Slither](https://github.com/crytic/slither)"},{"head":"Write (45 min): For each of the four parts, argue honestly whether a blockchain beats a shared database, and say so where it doesn't","links":""},{"head":"Write (90 min): README with an architecture diagram, a 5-minute demo video of the full flow, and the capstone post","links":""},{"head":"Write (30 min): Log: what you'd change with another month","links":""},{"head":"AI (15 min): GenAI provenance: read the C2PA overview, then add a paragraph to your capstone README on how the same sign-and-anchor pattern could prove where a photo or AI-generated output came from","links":"[C2PA](https://c2pa.org/)"},{"head":"Capstone (45 min): Compliance check: anyone can mark a batch non-compliant by submitting a signed reading outside the policy range with its Merkle proof, and a missing step or wrong role also fails. Test one compliant batch and one failing batch","links":""},{"head":"Capstone (30 min): Demo site v1, open to everyone with no login: Explore (sample batches), Market (listings) and Trace (enter a batch id or scan its QR code to see the journey, who signed each step, the readings summary and compliance status), reading from your deployed contracts. Build it in trust-stack/app/site/ following trust-stack/app/README.md","links":""},{"head":"Capstone (30 min): Deploy for real: forge script with your keystore account to Base Sepolia, verify on Basescan, record addresses and read-only checks in deployments/base-sepolia.json (copy the example), and run make smoke until every check is green","links":"[Base docs](https://docs.base.org/)"},{"head":"Capstone (15 min): Make it public: put the trace page in trust-stack/app/site/ so it publishes to GitHub Pages, then check the README's Trust stack badge, Codespaces button and DEMO.md all work from a logged-out browser","links":""}]},"12":{"title":"Agents with wallets, verifiable AI, and a retrospective","goal":"Give an LLM agent spending power that a contract limits, try to break it, and learn what zkML can and can't prove.","deliver":"Project 7 (guarded agent wallet with a red-team report), an implications memo, and your retrospective","tasks":[{"head":"Learn (30 min): Vitalik Buterin: The promise and challenges of crypto + AI applications","links":"[vitalik.eth.limo](https://vitalik.eth.limo/general/2024/01/30/cryptoai.html)"},{"head":"Learn (30 min): ERC-4337 motivation, then EIP-7702","links":"[ERC-4337](https://eips.ethereum.org/EIPS/eip-4337) · [EIP-7702](https://eips.ethereum.org/EIPS/eip-7702)"},{"head":"Learn (30 min): x402 docs: the quickstart","links":"[docs.x402.org](https://docs.x402.org/) · [x402 on GitHub](https://github.com/x402-foundation/x402)"},{"head":"Learn (20 min): ERC-8004 abstract and motivation","links":"[ERC-8004](https://eips.ethereum.org/EIPS/eip-8004)"},{"head":"Learn (20 min): Simon Willison on prompt injection: two posts","links":"[Prompt injection series](https://simonwillison.net/series/prompt-injection/)"},{"head":"Build (105 min): Build a guarded agent wallet that pays through your TestUSD rail: a contract wallet with a daily cap and a recipient allowlist, and an LLM with a single 'pay' tool. Try five injection prompts and record what the contract blocked","links":""},{"head":"Write (30 min): Log: which defences held in the model and which only held in the contract","links":""},{"head":"Learn (30 min): Vitalik Buterin: an approximate introduction to how zk-SNARKs are possible","links":"[vitalik.eth.limo](https://vitalik.eth.limo/general/2021/01/26/snarks.html)"},{"head":"Learn (30 min): EZKL: read the getting-started guide and run its example (the full build is optional)","links":"[EZKL docs](https://docs.ezkl.xyz/getting-started/) · [ezkl on GitHub](https://github.com/zkonduit/ezkl)"},{"head":"Write (45 min): Memo: custody for autonomous agents, accountability, energy, and the current rules in Rwanda, Nigeria and the EU (check these; they change)","links":"[EU MiCA (ESMA)](https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica)"},{"head":"Write (60 min): Retrospective: pick the next direction (ZK, auditing, DePIN, or agent payments)","links":""},{"head":"Build (20 min): Proof of learning (Capstone D): issue yourself a credential for each finished week, with that week's folder commit hash as evidence, and verify one on the testnet","links":""},{"head":"Crypto (30 min): Zero-knowledge in practice. Read the first chapters of the RareSkills ZK Book, then revisit what your EZKL proof actually proved","links":"[RareSkills ZK Book (free)](https://www.rareskills.io/zk-book)"},{"head":"Apps (30 min): Other applications, one paragraph each on who has to trust whom: tokenised real-world assets, DAOs and on-chain governance, prediction markets, and DePIN networks","links":"[ethereum.org: DAOs](https://ethereum.org/en/dao/) · [Helium docs (DePIN example)](https://docs.helium.com/)"},{"head":"Capstone (30 min): Seed the live demo: put throwaway actor keys in trust-stack/.env (never your real wallet), run make seed so the sample batches, listings and one failing batch exist on Base Sepolia, then make smoke. Rerun make seed any time to top it up","links":"[Foundry: keystores (cast wallet)](https://getfoundry.sh/cast/reference/cast-wallet-import)"},{"head":"Capstone (60 min): Admin console: an Admin tab that appears only when the connected wallet holds the issuer role on-chain. From it, issue a credential, create a batch, record a step and anchor readings, so you can show something new live. The contracts enforce the role; the page only hides the buttons","links":"[viem: writing to contracts](https://viem.sh/docs/contract/writeContract)"}]},"capstone_title":"Capstone, a four-part trust stack"}''')


def plan_end(text: str) -> int:
    i = text.find("\n---\n")
    return len(text) if i < 0 else i


def week_span(text: str, week: int) -> tuple[int, int]:
    """Start/end offsets of one week's section inside the plan part of a README."""
    end = plan_end(text)
    heads = [m for m in WEEK_HEAD_RE.finditer(text[:end])]
    if not heads:
        return 0, end
    for i, m in enumerate(heads):
        if int(m.group(1)) == week:
            return m.start(), heads[i + 1].start() if i + 1 < len(heads) else end
    return -1, -1


def task_block(mark: str, head: str, links: str) -> str:
    return f"- [{mark}] {head}" + (f"  \n  {links}" if links else "")


def upgrade_week(text: str, week: int, spec: dict) -> tuple[str, int, int]:
    start, end = week_span(text, week)
    if start < 0:
        return text, 0, 0
    section = text[start:end]
    # Each task = a checkbox line plus an optional indented links line right after it.
    blocks = []
    for m in BOX_RE.finditer(section):
        s, e = m.start(), m.end()
        nxt = section[e + 1:].split("\n", 1)[0] if e < len(section) else ""
        if nxt.startswith("  ") and "](" in nxt:
            e = e + 1 + len(nxt)
        head = m.group(2).rstrip()
        blocks.append((s, e, m.group(1), head))
    changed = added = 0
    # Rewrite changed tasks, from the end so offsets stay valid.
    for i in range(min(len(blocks), len(spec["tasks"])) - 1, -1, -1):
        s, e, mark, head = blocks[i]
        want = spec["tasks"][i]
        if head != want["head"]:
            section = section[:s] + task_block("x" if mark.lower() == "x" else " ", want["head"], want["links"]) + section[e:]
            changed += 1
    # Append new tasks after the last one.
    if len(spec["tasks"]) > len(blocks):
        last = list(BOX_RE.finditer(section))[-1]
        e = last.end()
        nxt = section[e + 1:].split("\n", 1)[0]
        if nxt.startswith("  ") and "](" in nxt:
            e = e + 1 + len(nxt)
        extra = "\n".join(task_block(" ", t["head"], t["links"]) for t in spec["tasks"][len(blocks):])
        section = section[:e] + "\n" + extra + section[e:]
        added = len(spec["tasks"]) - len(blocks)
    # Title, goal and ship lines inside this week's section.
    section = re.sub(r"^(## Week \d+: ).*$", lambda m: m.group(1) + spec["title"], section, count=1, flags=re.M)
    section = re.sub(r"^\*\*Goal:\*\* .*$", lambda m: "**Goal:** " + spec["goal"], section, count=1, flags=re.M)
    section = re.sub(r"^\*\*Ship:\*\* .*$", lambda m: "**Ship:** " + spec["deliver"], section, count=1, flags=re.M)
    return text[:start] + section + text[end:], changed, added


def main() -> None:
    for folder in sorted(ROOT.iterdir()):
        m = FOLDER_RE.match(folder.name)
        if not (folder.is_dir() and m):
            continue
        readme = folder / "README.md"
        text = readme.read_text(encoding="utf-8")
        before = text
        a, b = int(m.group(1)), int(m.group(2) or m.group(1))
        report = []
        for week in range(a, b + 1):
            text, changed, added = upgrade_week(text, week, PLAN[str(week)])
            if changed or added:
                report.append(f"week {week}: {added} added, {changed} updated")
        # Folder title (first line)
        if a == b:
            text = re.sub(r"^# Week \d+: .*$", f"# Week {a:02d}: {PLAN[str(a)]['title']}", text, count=1, flags=re.M)
        else:
            text = re.sub(r"^# Weeks .*$", f"# Weeks {a}–{b}: {PLAN['capstone_title']}", text, count=1, flags=re.M)
        if text != before:
            readme.write_text(text, encoding="utf-8")
            print(f"{folder.name}: " + ("; ".join(report) or "titles updated"))
    subprocess.run([sys.executable, str(ROOT / "scripts" / "update_progress.py")], check=True)


if __name__ == "__main__":
    main()
